// Safe input handling for Section 01
let inputData;
try {
  inputData = $input.first().json;
  console.log('✅ Input received for Section 01');
  console.log('📋 Keys:', Object.keys(inputData || {}));
} catch (error) {
  console.error('❌ Input error:', error.message);
  inputData = {};
}

// Extract data safely with fallbacks
const companyId = inputData?.company_id || 'unknown';
const companyName = inputData?.company_name || 'Unknown Company';
const companyFolderName = inputData?.company_folder_name || companyName;

console.log('🔄 SECTION 01: Introduction & Engagement Context');
console.log('═'.repeat(50));
console.log('🏢 Company:', companyName);
console.log('🆔 ID:', companyId);
console.log('═'.repeat(50));

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    company_folder_name: companyFolderName,
    section_number: 1,
    section_title: 'Introduction & Engagement Context',
    processing_status: 'initialized',
    started_at: new Date().toISOString()
  }
};

// Create enhanced prompt with RAG knowledge
const sectionData = $node['Initialize Section 01'].json;
const ragResults = $input.first().json;

console.log('🔍 Creating enhanced prompt for:', sectionData.company_name);

// Extract knowledge from RAG
let knowledgeContext = 'General business due diligence principles and methodologies.';
if (ragResults && ragResults.documents && ragResults.documents.length > 0) {
  console.log('📚 Found', ragResults.documents.length, 'RAG documents');
  knowledgeContext = ragResults.documents.map((doc, i) => 
    `Knowledge ${i + 1}: ${doc.pageContent}`
  ).join('\n\n');
} else {
  console.log('ℹ️ No RAG documents found, using general context');
}

// Create the enhanced prompt
const enhancedPrompt = `You are a Big 4 consulting firm senior analyst creating a professional due diligence report.

Generate a comprehensive "Introduction & Engagement Context" section for: ${sectionData.company_name}

KNOWLEDGE BASE CONTEXT:
${knowledgeContext}

REQUIREMENTS:
1. Write in formal Big 4 consulting style
2. Include engagement scope, methodology, and objectives  
3. Reference Big 4 due diligence standards and frameworks
4. Explain the business context and market relevance
5. Minimum 400 words with clear professional structure
6. Use specific business terminology
7. Include timeframe and deliverable expectations

Structure with these subsections:
- Engagement Overview
- Scope and Methodology
- Business Context  
- Due Diligence Framework
- Expected Outcomes

Generate professional content that sets the foundation for comprehensive due diligence analysis.`;

console.log('✅ Enhanced prompt created');
console.log('📏 Length:', enhancedPrompt.length);

return {
  json: {
    ...sectionData,
    enhanced_prompt: enhancedPrompt,
    knowledge_context: knowledgeContext,
    rag_documents_found: ragResults?.documents?.length || 0
  }
};

// Process and format the generated content
const report = $input.first().json.response || '';
const promptData = $node['Create Enhanced Prompt'].json;

console.log('📄 Processing Section 01 content');
console.log('📏 Raw length:', report.length);

if (!report || report.length < 100) {
  console.error('❌ Content generation failed');
  return {
    json: {
      company_id: promptData.company_id,
      company_name: promptData.company_name,
      section_number: 1,
      title: promptData.section_title,
      content: 'ERROR: Section 01 content generation failed. Please check Ollama service.',
      status: 'failed',
      error: 'Content generation failed'
    }
  };
}

// Clean the content
const cleanContent = report
  .replace(/\{\{[^}]*\}\}/g, '')
  .replace(/\$[a-zA-Z0-9_.\[\]]+/g, '')
  .replace(/\s+/g, ' ')
  .trim();

console.log('✅ Section 01 generated successfully');
console.log('📊 Final length:', cleanContent.length);
console.log('🎯 RAG enhanced:', promptData.rag_documents_found > 0);

return {
  json: {
    company_id: promptData.company_id,
    company_name: promptData.company_name,
    section_number: 1,
    title: promptData.section_title,
    content: cleanContent,
    status: 'approved',
    rag_enhanced: true,
    rag_documents_used: promptData.rag_documents_found,
    word_count: cleanContent.length,
    generated_at: new Date().toISOString(),
    approved_at: new Date().toISOString()
  }
};
